/* === 怪奇物语 (Stranger Things) 主题 === */
/* 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.*/

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Permanent+Marker&family=Shadows+Into+Light&display=swap');
@import url("https://fontsapi.zeoseven.com/2102/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  
@import url("https://fontsapi.zeoseven.com/2104/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/20/main/result.css");  

/* --- 2. 核心颜色与变量 --- */
:root {
    --theme-bg-color: #0d0d0d; 
    --theme-bg-mid: #1a1a1a; 
    --card-bg: #151515; 
    --accent-red: #D52B1E;
    --text-main: #E5E5E5; 
    --text-subtle: #A3A3A3; 

    --font-english-hand: 'Permanent Marker', cursive;
    --font-english-serif: 'Shadows Into Light', cursive;
    --font-main: "YouchaSanz Light", var(--font-english-serif), sans-serif;
    --font-quote: "RealTypeWriter Light", var(--font-english-hand), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "Xiangcui Wave Sans Xiangcui Wave Sans", var(--font-english-hand), sans-serif;
}

/* --- 3. 全局样式：无阴影、无边框、复古网格背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: repeating-linear-gradient(rgba(213, 43, 30, 0.04) 0px, rgba(213, 43, 30, 0.04) 1px, transparent 1px, transparent 30px),
                      repeating-linear-gradient(90deg, rgba(213, 43, 30, 0.04) 0px, rgba(213, 43, 30, 0.04) 1px, transparent 1px, transparent 30px) !important;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-red); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 (纯正SVG替换) --- */
#top-settings-holder { position:relative; background-color: rgba(10, 10, 10, 0.8); backdrop-filter: blur(10px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s ease; }
.drawer-icon.fa-fw:hover { transform: scale(1.1) rotate(5deg); filter: drop-shadow(0 0 5px var(--accent-red)); }

/* D20 骰子 (纯SVG) */
.drawer-icon.fa-sliders, .drawer-icon.fa-font, .drawer-icon.fa-user, .drawer-icon.fa-cubes, .drawer-icon.fa-face-smile, #ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon {
    background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23D52B1E' stroke-width='2'%3e%3cpolygon points='12 2 2 10 12 22 22 10'/%3e%3cpolygon points='12 2 8 10 12 22'/%3e%3cpolygon points='12 2 16 10 12 22'/%3e%3cline x1='2' y1='10' x2='22' y2='10'/%3e%3c/svg%3e");
}
/* 复古磁带 (纯SVG) */
.drawer-icon.fa-plug, .drawer-icon.fa-book-atlas, .drawer-icon.fa-image, .drawer-icon.fa-bars-progress, .drawer-icon.fa-panorama, #sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #table_database_settings_drawer .drawer-icon {
    background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23D52B1E' stroke-width='2'%3e%3crect x='2' y='5' width='20' height='14' rx='2'/%3e%3ccircle cx='8' cy='12' r='2'/%3e%3ccircle cx='16' cy='12' r='2'/%3e%3cpath d='M10 12h4'/%3e%3c/svg%3e");
}
/* 拍立得 (纯SVG) */
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23D52B1E' stroke-width='2'%3e%3crect x='3' y='4' width='18' height='16' rx='2'/%3e%3ccircle cx='12' cy='12' r='4'/%3e%3cpath d='M8 4v-2h8v2'/%3e%3c/svg%3e");
}

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(10, 10, 10, 0.9), rgba(10, 10, 10, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/orL0/1200X675/4c84e64d697d0084c282037338ae38e0.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 0px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 0px !important; 
    background-color: rgba(15, 15, 15, 0.85) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; 
    -webkit-backdrop-filter: blur(10px) !important; 
    border: none !important; 
    box-shadow: none !important; 
    transition: all 0.3s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { transform: translateY(-3px); background-color: rgba(20, 20, 20, 0.95) !important; }

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1.1rem !important; box-shadow: none !important; font-family: var(--font-english-serif); }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 伪提示词 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'BROADCASTING TO THE UPSIDE DOWN... 📻'; 
    color: var(--accent-red); 
    position: absolute; 
    top: 50%; transform: translateY(-50%); 
    left: 50px; right: 70px; 
    text-align: center; 
    font-family: var(--font-english-hand); 
    font-size: clamp(1rem, 2.5vw, 1.3rem); 
    pointer-events: none; 
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    opacity: 0.8; 
    animation: flicker 4s infinite alternate;
}
@keyframes flicker { 0% { opacity: 1; } 5% { opacity: 0.4; } 10% { opacity: 1; } 15% { opacity: 0.2; } 20% { opacity: 1; } 100% { opacity: 1; } }

/* 底栏贴图 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 36px; height: 36px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; 
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.15) rotate(10deg); filter: drop-shadow(0 0 5px var(--accent-red)); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/Yup6/1222X1268/2026-05-02%2520155723.png/webp'); }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/Uh2z/1724X1319/2026-05-02%2520155635.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/f9P6/1800X1654/2026-05-02%2520155707.png/webp'); }

/* --- 6. 核心：消息框 (红线链接与大照片) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 140px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
    position: relative;
}

/* 侦探板红线牵引效果 */
.mes::before {
    content: '';
    position: absolute;
    top: 390px; 
    left: 48%;
    width: 3px;
    height: 100px;
    background-color: var(--accent-red);
    box-shadow: inset 1px 0 2px rgba(0,0,0,0.5);
    transform: rotate(12deg);
    z-index: 10;
}
.mes[is_user="true"]::before { left: 52%; transform: rotate(-12deg); }

/* --- 消息框顶部背景图 --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 400px !important; 
    min-height: 400px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 0px;
    border: none !important; 
    background-color: transparent !important; 
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/id7U/1200X800/f74c607d687c4ce6103e0e2be3d391f1.jpg/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/jRVc/4578X2298/2026-05-02%2520155842.png/webp'); }

/* 顶端胶布效果 */
.mes .mesAvatarWrapper::after {
    content: ''; position: absolute; top: -15px; left: 50%; transform: translateX(-50%) rotate(-2deg);
    width: 120px; height: 35px; background-color: rgba(220, 220, 220, 0.85);
    z-index: 40; filter: contrast(1.2) sepia(0.5); border: none;
}

/* --- 拍立得照片风格头像框 --- */
.mes .avatar {
    position: absolute;
    top: 50%; 
    width: 220px !important; height: 260px !important; 
    background: #e6e6e6 !important; 
    padding: 15px 15px 65px 15px !important; 
    z-index: 30; display: flex !important; align-items: flex-start; justify-content: center;
    border-radius: 0px !important; 
    border: none !important;
}
.mes[is_user="false"] .avatar { left: 20px; transform: translateY(-50%) rotate(-4deg); }
.mes[is_user="true"] .avatar { right: 20px; left: auto; transform: translateY(-50%) rotate(4deg); }

.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 0px !important; filter: contrast(1.1) grayscale(0.2);
}

/* 照片图钉与绝密标记 */
.mes .avatar::before {
    content: '📍'; position: absolute; top: -15px; left: 50%; transform: translateX(-50%);
    font-size: 32px; z-index: 50;
}
.mes .avatar::after {
    content: 'EVIDENCE \A DO NOT TOUCH'; white-space: pre; position: absolute;
    bottom: 15px; left: 0; right: 0; text-align: center;
    font-family: var(--font-english-hand); font-size: 16px; color: var(--accent-red); line-height: 1.2; letter-spacing: 1px;
    transform: rotate(-3deg);
}

/* --- 名字 (Dymo打字机压印标签带) --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: inline-flex !important; position: relative !important; 
    top: auto !important; bottom: auto !important; 
    background: #000 !important;
    border: none !important; border-radius: 0 !important;
    padding: 4px 12px !important; 
    z-index: 40 !important; align-items: center !important; gap: 12px !important;
    transform: rotate(-2deg) !important;
    width: fit-content !important; max-width: 85% !important; 
    white-space: normal !important; word-break: break-word !important; 
}
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { margin-left: 15px !important; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { margin-right: 15px !important; align-self: flex-end !important; }

.mes .ch_name .name_text { font-family: var(--font-quote) !important; font-size: 18px !important; letter-spacing: 2px; color: #fff !important; text-transform: uppercase; }

/* --- 楼层与时间戳 (左右分离的绝密标签) --- */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important; top: -16px !important; 
    background-color: #000 !important; padding: 4px 12px !important;
    color: var(--accent-red) !important; font-size: 14px !important; font-family: var(--font-quote) !important; 
    letter-spacing: 1px !important; white-space: nowrap; z-index: 40 !important;
    border: none !important; border-radius: 0 !important;
}
.mes .mesIDDisplay { left: 20px !important; transform: rotate(-2deg) !important; }
.mes .mes_timer { right: 20px !important; left: auto !important; transform: rotate(2deg) !important; }
.mesIDDisplay::before { content: 'LOG # '; }
.mesIDDisplay::after { content: ' [HAWKINS LAB]'; }

@media (min-width: 800px) {
    .mes[is_user="false"] .avatar { left: 80px !important; }
    .mes[is_user="true"] .avatar { right: 80px !important; }
}

/* --- 消息正文：黑色绝密档案袋 --- */
.mes .mes_block { 
    margin-top: 80px !important; 
    background-color: var(--card-bg) !important; 
    padding: 40px !important; 
    position: relative; 
    border: none !important; 
    min-height: 120px !important; 
    z-index: 10; 
    background-image: none !important; 
    overflow: visible !important; 
    clip-path: none !important; 
    -webkit-mask-image: none !important;
}

/* 档案袋顶部机密标签 */
.mes .mes_block::before {
    position: absolute;
    top: -26px; 
    height: 26px;
    width: 180px;
    background-color: var(--accent-red);
    color: #fff;
    font-family: var(--font-english-hand);
    font-size: 14px;
    line-height: 26px;
    text-align: center;
    z-index: 10;
    letter-spacing: 1px;
}
.mes[is_user="false"] .mes_block::before { content: 'CONFIDENTIAL FILE'; left: 0; }
.mes[is_user="true"] .mes_block::before { content: 'FIELD NOTES'; right: 0; left: auto; background-color: var(--theme-bg-mid); }

/* 图钉扎在档案袋上 */
.mes .mes_block::after {
    content: '📌';
    position: absolute;
    top: -16px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 28px;
    z-index: 20;
}

/* 背景隐约的英文装饰涂鸦 */
.mes_block .mes_text::after {
    content: 'THE DEMOGORGON \A IS COMING'; white-space: pre;
    position: absolute; bottom: 10px; color: rgba(213, 43, 30, 0.04);
    font-family: var(--font-english-hand); font-size: 40px; text-align: center; font-weight: bold; transform: rotate(-10deg);
    z-index: 0; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block .mes_text::after { right: 20px; }
.mes[is_user="true"] .mes_block .mes_text::after { left: 20px; }

/* 思维链自定义 (融入闪烁灯效) */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "FLICKERING LIGHTS... (DECIPHERING)"; 
    font-family: var(--font-english-hand); font-size: 20px !important; 
    color: var(--accent-red); visibility: visible; letter-spacing: 2px; 
    animation: flicker 4s infinite;
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 4px; 
    background: repeating-linear-gradient(45deg, var(--accent-red), var(--accent-red) 4px, transparent 4px, transparent 8px);
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* 颤抖打字指示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/f9P6/1800X1654/2026-05-02%2520155707.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pulse-shake 1.5s infinite alternate; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse-shake { 0% { transform: scale(1) rotate(-3deg); } 100% { transform: scale(1.1) rotate(3deg); } }

/* --- 悬浮按钮 --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(10, 10, 10, 0.9) !important; color: var(--accent-red) !important; padding: 6px !important; border-radius: 0 !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-red) !important; color: #fff !important; transform: scale(1.1) rotate(5deg); }

/* --- 全局UI设定 (无圆角、无边框) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(20, 20, 20, 0.9) !important; border-radius: 0 !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--accent-red) !important; border: none !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(30,30,30,0.9) !important; color: var(--text-main) !important; border-radius: 0 !important; padding: 10px !important; border: none !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: #222 !important; }
.menu_button { background-color: rgba(30, 30, 30, 0.8) !important; color: var(--text-main) !important; transition: all 0.3s ease; border-radius: 0 !important; border: none !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-red) !important; color: white !important; transform: translateY(-2px); }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-red) !important; }

dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(10, 10, 10, 0.95); z-index: 0; border-radius: 0; border: none !important; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(30,30,30,0.9) !important; color: var(--text-main) !important; border-radius: 0 !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; border: none !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-red) !important; color: #fff !important; transform: translateY(-2px) rotate(-2deg) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--text-subtle) !important; color: #000 !important; transform: translateY(-2px) rotate(2deg) !important; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    .mes { margin: 120px auto 40px !important; }
    .mes .mesAvatarWrapper { height: 250px !important; min-height: 250px !important; margin-bottom: 30px; }
    .mes > .ch_name, .mes .mes_block > .ch_name { padding: 4px 10px !important; }
    .mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { margin-left: 10px !important; }
    .mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { margin-right: 10px !important; }
    .mes .ch_name .name_text { font-size: 16px !important; }

    .mes .avatar { width: 140px !important; height: 180px !important; padding: 10px 10px 45px 10px !important; }
    .mes .avatar::after { font-size: 10px; bottom: 10px; }

    .mes .mes_block { padding: 30px 20px 30px 20px !important; margin-top: 50px !important; }
    .mes .mes_block::before { width: 120px; height: 22px; line-height: 22px; top: -22px; font-size: 11px; }
    .mes .mesIDDisplay { left: 10px !important; }
    .mes .mes_timer { right: 10px !important; }

    .mes::before { top: 250px; height: 80px; } /* 缩短手机端侦探板红线 */
}
